  @shape  ({ {idx = n, ordinal = n}, ... }, root, pos)  @ 1002
  @shape  assignment = { [slotIdx] = base, ... } -- a MIDI slot the map omits is pinned  @ 1045
  @shape  bases = { 'Bassline', 'Drums', ... } -- the roots in use, sorted  @ 1091

